function probs(pl, own, opp, home, b2bOwn, b2bOpp, gkSv, C, S){
  const lg=S.league, T=S.teams;
  const f={def_opp:Math.log(T[opp][1]), att_own:Math.log(T[own][0]), sdef_opp:Math.log(T[opp][3]), satt_own:Math.log(T[own][2]),
           gk_opp:Math.log((1-gkSv)/(1-lg.Lsv)), ha:home?0.5:-0.5, b2b_own:b2bOwn?1:0, b2b_opp:b2bOpp?1:0, ppsh:pl.pp_share-C.priors[pl.pos].pp_share};
  const eta=(m,base)=>{let e=C.coef[m].const; for(const k in C.coef[m]){ if(k==='const')continue; e+=C.coef[m][k]*(k==='lbase'?Math.log(base):k==='lgtrend'?Math.log(lg.tendencia[m][pl.pos]):f[k]); } return e;};
  const toi=pl.toi_esperado_min;
  const lg1=Math.exp(eta('golo_1mais', pl.golos60/60*toi)), lp1=Math.exp(eta('ponto_1mais', pl.pontos60/60*toi));
  const mu=Math.exp(eta('remates', pl.remates60/60*toi)), r=C.r;
  let p=[Math.pow(r/(r+mu),r)]; for(let k=0;k<3;k++) p.push(p[k]*(k+r)/(k+1)*mu/(r+mu));
  return {golo:1-Math.exp(-lg1), ponto:1-Math.exp(-lp1), rem15:1-p[0]-p[1], rem25:1-p[0]-p[1]-p[2], rem35:1-p[0]-p[1]-p[2]-p[3]};
}
